"""Audit V4-002 on perturbations generated by the claimed carrier.

The full native Floquet spectrum remains a useful worst-case diagnostic, but
V4 only claims a localized Dirac carrier.  This audit therefore launches the
two cubical four-component copies with both momentum signs in the three axes
and a held diagonal, using the same two-layer C19/centered-time preparation as
the movement comparator.  It evolves those perturbations with the unrestricted
native tangent recurrence and asks whether the previously reported instability
is actually reached by the claimed carrier sector.

No projection, reset, or Dirac force is applied to the native recurrence.
Dirac supplies only the independently evolved comparison columns.
"""

from __future__ import annotations

import argparse
import hashlib
import itertools
import json
from pathlib import Path
import sys

import numpy as np
from scipy.sparse import csc_matrix
from scipy.sparse.linalg import splu


HERE = Path(__file__).resolve().parent


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def sparse(value: np.ndarray, tolerance: float) -> csc_matrix:
    result = value.copy()
    result[np.abs(result) < tolerance] = 0.0
    return csc_matrix(result)


def orth(columns: np.ndarray) -> np.ndarray:
    u, singular, _ = np.linalg.svd(columns, full_matrices=False)
    cutoff = 1e-11 * max(float(singular[0]), 1.0)
    return u[:, singular > cutoff]


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--tangent-cache", type=Path, required=True)
    parser.add_argument("--rest-cache", type=Path, required=True)
    parser.add_argument("--action-module", type=Path,
                        default=Path("live_clifford_bond_action.py"))
    parser.add_argument(
        "--chi-scale-json", type=Path,
        help=("Optional native envelope-closure artifact supplying one "
              "complex chi/Psi tangent ratio per cubical flavor. When "
              "omitted the historical Psi-only launch is retained."))
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--cycles", type=float, default=100.0)
    parser.add_argument("--wave-number", type=float, default=0.35)
    parser.add_argument("--packet-width", type=float, default=1.35)
    parser.add_argument("--sparse-tolerance", type=float, default=1e-11)
    parser.add_argument("--dt", type=float)
    parser.add_argument("--action-scale", type=float, default=6/19)
    parser.add_argument("--spacetime-scale", type=float, default=6/361)
    parser.add_argument("--parallel-matched-scale", type=float, default=1.0)
    parser.add_argument("--parallel-clock-potential-scale", type=float,
                        default=1.0)
    args = parser.parse_args()

    tangent_cache = args.tangent_cache.resolve()
    rest_cache = args.rest_cache.resolve()
    action_module = (args.action_module if args.action_module.is_absolute()
                     else HERE/args.action_module).resolve()
    chi_scale_json = None
    if args.chi_scale_json is not None:
        chi_scale_json = (args.chi_scale_json
                          if args.chi_scale_json.is_absolute()
                          else HERE/args.chi_scale_json).resolve()
    if not tangent_cache.is_file():
        raise FileNotFoundError(tangent_cache)
    if not rest_cache.is_file():
        raise FileNotFoundError(rest_cache)
    if not action_module.is_file():
        raise FileNotFoundError(action_module)
    if chi_scale_json is not None and not chi_scale_json.is_file():
        raise FileNotFoundError(chi_scale_json)

    chi_scales = {"plus": 0j, "minus": 0j}
    if chi_scale_json is not None:
        scale_evidence = json.loads(chi_scale_json.read_text(
            encoding="utf-8"))
        for row in scale_evidence["rows"]:
            case = next(item for item in row["cases"]
                        if item["envelope"] == "all_125_centers")
            chi_scales[row["flavor"]] = complex(
                case["chi_scale_real"], case["chi_scale_imag"])

    # Import the checked-in preparation/readout code, but point its historical
    # rest-state loader at the explicitly supplied immutable cache.
    sys.path.insert(0, str(HERE))
    import personal_touch_unit_geometric_canonical as canonical
    canonical.CACHE = rest_cache
    import canonical_noncoplanar_bifurcation_audit as native_time
    import canonical_transfer_oscillator_spectrum as native_spectrum
    import cube_incidence_extended_packet_gate as dirac
    import current_action_localized_envelope_closure as envelope

    data = np.load(tangent_cache)
    previous, current, following = (
        data[name] for name in ("previous", "current", "following"))
    dimension = current.shape[0]
    rest = np.load(rest_cache)["rest"]
    if rest.shape != (dimension,):
        raise ValueError("rest state and tangent cache dimensions differ")

    dt = native_time.DT if args.dt is None else args.dt
    theta = float(np.arccos(1-dt**2*native_time.CHI0**2/2))
    rotate_minus = native_spectrum.rotation_matrix(dimension, -theta)
    rotate_plus = native_spectrum.rotation_matrix(dimension, theta)
    lhs = sparse(following@rotate_plus, args.sparse_tolerance)
    current_operator = sparse(current, args.sparse_tolerance)
    previous_operator = sparse(previous@rotate_minus, args.sparse_tolerance)
    factor = splu(lhs)

    psi_frame, chi_frame, sites = envelope.carrier_frames(rest)
    cases = []
    native_previous = []
    native_current = []
    target_initial = []
    for flavor, basis in dirac.flavor_bases().items():
        alpha, beta = dirac.compressed_clifford(basis)
        raw = envelope.raw_columns(
            basis, psi_frame, chi_frame, sites, dirac.OFFSETS,
            chi_scales[flavor])
        for axis in (0, 1, 2, 3):
            for sign in (-1, 1):
                packet_previous, packet_current, _, momentum = dirac.packet(
                    axis, sign, alpha, beta, dt,
                    width=args.packet_width,
                    carrier_wave_number=args.wave_number,
                    centered_time=True,
                    frequency_branch="negative",
                    transport_scale=1.0)
                q_previous = raw@dirac.real_coordinates(packet_previous)
                q_current = raw@dirac.real_coordinates(packet_current)
                native_previous.append(q_previous)
                native_current.append(q_current)
                target_initial.append(packet_current)
                cases.append({
                    "flavor": flavor,
                    "axis": "diagonal" if axis == 3 else "xyz"[axis],
                    "axis_index": axis,
                    "sign": sign,
                    "momentum": momentum.tolist(),
                    "raw": raw,
                    "alpha": alpha,
                    "beta": beta,
                })

    q_previous = np.column_stack(native_previous)
    q_current = np.column_stack(native_current)
    initial_phase = np.vstack((q_current, q_previous))
    phase_basis = orth(np.column_stack((
        initial_phase,
        np.vstack((
            np.column_stack([
                case["raw"]@dirac.real_coordinates(1j*field)
                for case, field in zip(cases, target_initial)]),
            np.column_stack([
                case["raw"]@dirac.real_coordinates(1j*field)
                for case, field in zip(cases, [
                    dirac.centered_dirac_step(
                        initial, case["alpha"], case["beta"], -1, dt,
                        "negative", 1.0)
                    for case, initial in zip(cases, target_initial)])]),
        )),
    )))
    q_following = factor.solve(
        -(current_operator@q_current+previous_operator@q_previous))
    first_native_phase = np.vstack((q_following, q_current))
    expected_first_now = []
    expected_first_before = []
    expected_first_i_now = []
    expected_first_i_before = []
    for case, initial in zip(cases, target_initial):
        now = dirac.centered_dirac_step(
            initial, case["alpha"], case["beta"], 1, dt,
            "negative", 1.0)
        expected_first_now.append(
            case["raw"]@dirac.real_coordinates(now))
        expected_first_before.append(
            case["raw"]@dirac.real_coordinates(initial))
        expected_first_i_now.append(
            case["raw"]@dirac.real_coordinates(1j*now))
        expected_first_i_before.append(
            case["raw"]@dirac.real_coordinates(1j*initial))
    expected_first_basis = orth(np.column_stack((
        np.vstack((np.column_stack(expected_first_now),
                   np.column_stack(expected_first_before))),
        np.vstack((np.column_stack(expected_first_i_now),
                   np.column_stack(expected_first_i_before))),
    )))
    first_leakage = first_native_phase-expected_first_basis@(
        expected_first_basis.T@first_native_phase)
    one_step_dirac_sector_leakage = float(
        np.linalg.norm(first_leakage)
        / max(np.linalg.norm(first_native_phase), 1e-30))

    carrier_set = set(sites)
    first_departure_rows = []
    for index, case in enumerate(cases):
        expected = expected_first_now[index]
        expected_i = expected_first_i_now[index]
        alignment = np.column_stack((expected, expected_i))
        coefficients, *_ = np.linalg.lstsq(
            alignment, q_following[:, index], rcond=1e-12)
        coefficient_norm = np.linalg.norm(coefficients)
        aligned = alignment@(
            coefficients/max(coefficient_norm, 1e-30))
        residual = (q_following[:, index]-aligned).reshape(
            dirac.SIDE, dirac.SIDE, dirac.SIDE, 12)
        residual_psi = residual[..., :3]+1j*residual[..., 3:6]
        residual_chi = residual[..., 6:9]+1j*residual[..., 9:12]
        psi_power = np.sum(np.abs(residual_psi)**2, axis=-1)
        chi_power = np.sum(np.abs(residual_chi)**2, axis=-1)
        total_power = float(np.sum(psi_power)+np.sum(chi_power))
        carrier_psi_power = 0.0
        carrier_chi_power = 0.0
        psi_frame_power = 0.0
        chi_frame_power = 0.0
        normal_power = 0.0
        for corner, site in enumerate(sites):
            carrier_psi_power += float(psi_power[site])
            carrier_chi_power += float(chi_power[site])
            departure = residual_psi[site]
            psi_component = np.vdot(psi_frame[corner], departure)
            chi_component = np.vdot(chi_frame[corner], departure)
            represented = (psi_component*psi_frame[corner]
                           + chi_component*chi_frame[corner])
            psi_frame_power += float(abs(psi_component)**2)
            chi_frame_power += float(abs(chi_component)**2)
            normal_power += float(np.vdot(
                departure-represented,
                departure-represented).real)
        site_power = psi_power+chi_power
        maximum_site = tuple(
            int(value) for value in np.unravel_index(
                int(np.argmax(site_power)), site_power.shape))
        exterior_power = max(
            total_power-carrier_psi_power-carrier_chi_power, 0.0)
        first_departure_rows.append({
            "flavor": case["flavor"],
            "axis": case["axis"],
            "sign": case["sign"],
            "relative_configuration_error": float(
                np.sqrt(total_power)/max(np.linalg.norm(expected), 1e-30)),
            "field_power_fractions": {
                "Psi": float(np.sum(psi_power)/max(total_power, 1e-300)),
                "chi": float(np.sum(chi_power)/max(total_power, 1e-300)),
            },
            "location_power_fractions": {
                "eight_carrier_sites": float(
                    (carrier_psi_power+carrier_chi_power)
                    / max(total_power, 1e-300)),
                "surroundings": float(
                    exterior_power/max(total_power, 1e-300)),
            },
            "carrier_Psi_local_frame_power_fractions": {
                "along_Psi_ray_amplitude_phase": float(
                    psi_frame_power/max(carrier_psi_power, 1e-300)),
                "toward_chi_ray_in_plane": float(
                    chi_frame_power/max(carrier_psi_power, 1e-300)),
                "outside_local_Psi_chi_plane": float(
                    normal_power/max(carrier_psi_power, 1e-300)),
            },
            "maximum_departure_site": list(maximum_site),
            "maximum_site_is_carrier": maximum_site in carrier_set,
        })
    first_departure_worst = max(
        first_departure_rows,
        key=lambda row: row["relative_configuration_error"])

    steps = int(np.ceil(args.cycles*2*np.pi/native_time.CHI0/dt))
    requested_cycles = (0.0, 1.0, 2.0, 5.0, 10.0, 20.0, 50.0,
                        args.cycles)
    sample_steps = {
        min(steps, int(round(cycle*2*np.pi/native_time.CHI0/dt))): cycle
        for cycle in requested_cycles if cycle <= args.cycles
    }
    sample_steps[1] = dt*native_time.CHI0/(2*np.pi)
    samples = []

    def target_at(initial: np.ndarray, case: dict, step: int) -> np.ndarray:
        """Evaluate the centered Dirac comparator at an arbitrary step."""
        fourier = np.fft.fftn(initial, axes=(0, 1, 2))
        result = np.empty_like(fourier)
        frequencies = 2*np.pi*np.fft.fftfreq(dirac.SIDE)
        theta0 = float(np.arccos(
            1-dt**2*dirac.COMPARATOR_MASS**2/2))
        for index in itertools.product(range(dirac.SIDE), repeat=3):
            momentum = np.asarray([frequencies[value] for value in index])
            transport = dirac.c19_first_symbol(momentum, 1.0)
            hamiltonian = dirac.COMPARATOR_MASS*case["beta"]
            for axis in range(3):
                hamiltonian = (
                    hamiltonian+transport[axis]*case["alpha"][axis])
            energy = float(np.sqrt(
                dirac.COMPARATOR_MASS**2+transport@transport))
            theta_energy = float(np.arccos(np.clip(
                1-dt**2*energy**2/2, -1.0, 1.0)))
            laboratory = (
                np.cos(step*theta_energy)*np.eye(4)
                - 1j*np.sin(step*theta_energy)*hamiltonian/energy)
            # The selected comparison branch is the negative-frequency
            # branch in the carrier's co-rotating frame.
            corotating = np.exp(-1j*step*theta0)*laboratory
            result[index] = corotating@fourier[index]
        return np.fft.ifftn(result, axes=(0, 1, 2))

    def sample(step: int) -> None:
        rows = []
        for index, case in enumerate(cases):
            raw = case["raw"]
            target_field_now = target_at(target_initial[index], case, step)
            target_field_before = target_at(
                target_initial[index], case, step-1)
            target_now = raw@dirac.real_coordinates(target_field_now)
            target_before = raw@dirac.real_coordinates(target_field_before)
            target_i_now = raw@dirac.real_coordinates(1j*target_field_now)
            target_i_before = raw@dirac.real_coordinates(
                1j*target_field_before)
            target_phase = np.column_stack((
                np.concatenate((target_now, target_before)),
                np.concatenate((target_i_now, target_i_before)),
            ))
            native_phase = np.concatenate(
                (q_current[:, index], q_previous[:, index]))
            coefficients, *_ = np.linalg.lstsq(
                target_phase, native_phase, rcond=1e-12)
            length = np.linalg.norm(coefficients)
            aligned = target_phase@(coefficients/max(length, 1e-30))
            rows.append({
                "flavor": case["flavor"],
                "axis": case["axis"],
                "sign": case["sign"],
                "phase_aligned_relative_error": float(
                    np.linalg.norm(native_phase-aligned)
                    / max(np.linalg.norm(target_phase[:, 0]), 1e-30)),
                "phase_space_norm_ratio": float(
                    np.linalg.norm(native_phase)
                    / max(np.linalg.norm(target_phase[:, 0]), 1e-30)),
            })
        samples.append({
            "step": step,
            "cycles": step*dt*native_time.CHI0/(2*np.pi),
            "maximum_phase_aligned_relative_error": max(
                row["phase_aligned_relative_error"] for row in rows),
            "maximum_norm_ratio": max(
                row["phase_space_norm_ratio"] for row in rows),
            "minimum_norm_ratio": min(
                row["phase_space_norm_ratio"] for row in rows),
            "rows": rows,
        })

    for step in range(steps+1):
        if step in sample_steps:
            sample(step)
        if step == steps:
            break
        q_following = factor.solve(
            -(current_operator@q_current+previous_operator@q_previous))
        q_previous, q_current = q_current, q_following

    maximum_norm_ratio = max(
        sample_row["maximum_norm_ratio"] for sample_row in samples)
    maximum_shape_error = max(
        sample_row["maximum_phase_aligned_relative_error"]
        for sample_row in samples)
    final_sample = samples[-1]
    final_elapsed_time = final_sample["cycles"]*2*np.pi/native_time.CHI0
    observed_growth_rate = float(
        np.log(final_sample["maximum_norm_ratio"])
        / max(final_elapsed_time, 1e-30))
    # A factor-of-two envelope change was the predeclared material-growth
    # screen used to reject the predecessor.  Apply it to *any* physical
    # launch; the former minimum check could hide one growing case.
    material_growth = maximum_norm_ratio > 2.0
    result = {
        "stage": "V4-002",
        "status": "PHYSICAL_SECTOR_REACHABILITY_AUDIT",
        "action_module": action_module.name,
        "action_module_sha256": sha256(action_module),
        "chi_scale_source": (
            None if chi_scale_json is None else chi_scale_json.name),
        "chi_scales": {
            flavor: {"real": float(value.real),
                     "imag": float(value.imag)}
            for flavor, value in chi_scales.items()
        },
        "action_configuration": {
            "link_source": "joint_face_laplacian_plus_frame_oscillator",
            "action_scale": args.action_scale,
            "spacetime_scale": args.spacetime_scale,
            "parallel_matched_scale": args.parallel_matched_scale,
            "parallel_clock_potential_scale": (
                args.parallel_clock_potential_scale),
        },
        "tangent_cache": tangent_cache.name,
        "tangent_cache_sha256": sha256(tangent_cache),
        "rest_cache": rest_cache.name,
        "rest_cache_sha256": sha256(rest_cache),
        "dt": dt,
        "cycles": args.cycles,
        "steps": steps,
        "case_count": len(cases),
        "cases": [{key: value for key, value in case.items()
                   if key not in ("raw", "alpha", "beta")}
                  for case in cases],
        "initial_real_phase_space_rank": int(phase_basis.shape[1]),
        "one_step_dirac_sector_leakage": one_step_dirac_sector_leakage,
        "first_departure": {
            "rows": first_departure_rows,
            "worst_case": first_departure_worst,
            "interpretation": (
                "Residual after one unrestricted native update and one common "
                "phase alignment. Local-frame fractions decompose the Psi "
                "residual on the eight occupied sites into its rest Psi ray, "
                "the in-plane chi companion, and the remaining C3 direction."),
        },
        "maximum_phase_aligned_relative_error": maximum_shape_error,
        "maximum_phase_space_norm_ratio": maximum_norm_ratio,
        "final_minimum_phase_space_norm_ratio": (
            final_sample["minimum_norm_ratio"]),
        "observed_maximum_envelope_growth_rate_per_unit_time": (
            observed_growth_rate),
        "physical_launches_exhibit_material_growth": material_growth,
        "samples": samples,
        "verdict": (
            "PHYSICAL_LAUNCH_MATERIAL_GROWTH_OBSERVED"
            if material_growth else
            "NO_MATERIAL_GROWTH_IN_TESTED_PHYSICAL_LAUNCHES"),
        "claim_boundary": (
            "Tests the declared two-layer packet preparations for both "
            "cubical copies, both momentum signs, three axes, and a diagonal. "
            "It does not prove stability against arbitrary native-state "
            "perturbations, nonlinear finite-amplitude evolution, or external "
            "forcing. Dirac is an independent comparator only."),
    }
    output = args.output if args.output.is_absolute() else HERE/args.output
    output.write_text(json.dumps(result, indent=2, allow_nan=False)+"\n",
                      encoding="utf-8")
    print(json.dumps({key: value for key, value in result.items()
                      if key not in ("samples", "cases")}, indent=2))


if __name__ == "__main__":
    main()
